{
  "title": "The Bridge Out of the Ruined Crown",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers on a hill above the ruined city.",
      "visual_description": "Four cloaked figures crouched on a windy ridge at dusk, the broken silhouette of a royal city below with shattered towers and torn banners.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 2,
      "caption": "The map reader traces a route through the dead streets.",
      "visual_description": "A worn parchment map spread on a rock, lit by a small blue flame, fingers tracing a winding path past castle gates and a cursed tower.",
      "characters": ["map_reader", "magic_helper"]
    },
    {
      "scene_number": 3,
      "caption": "The scout slips ahead to test the outer gate.",
      "visual_description": "A light-footed figure in gray pressed against a massive iron-bound castle gate, listening, while rusted hinges drip moonlight.",
      "characters": ["scout"]
    },
    {
      "scene_number": 4,
      "caption": "An armored patrol marches past in the rubble street.",
      "visual_description": "Three dented armored guards with halberds tramping through broken cobblestones, torchlight flaring off their visors, the scout hidden behind a fallen statue.",
      "characters": ["scout", "armored_patrol"]
    },
    {
      "scene_number": 5,
      "caption": "Frightened townspeople whisper of a captive in the keep.",
      "visual_description": "Huddled villagers in a candlelit cellar, ragged clothes, pointing upward; the map reader leans in to listen.",
      "characters": ["map_reader", "frightened_townspeople"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a dragon coil through the market square.",
      "visual_description": "Empty market stalls with scorch marks, an enormous clawed footprint pressed into ash, the scout staring up at a smoke-stained sky.",
      "characters": ["scout", "frightened_townspeople"]
    },
    {
      "scene_number": 7,
      "caption": "The sleepy official insists on stopping for tea.",
      "visual_description": "A round, yawning bureaucrat in mismatched robes lighting a tiny kettle on a rubble pile, the magic helper rolling glowing eyes.",
      "characters": ["sleepy_official", "magic_helper"]
    },
    {
      "scene_number": 8,
      "caption": "Old royal banners rot above the inner courtyard.",
      "visual_description": "Tattered crimson banners with faded gold crowns hanging from cracked archways, the team creeping single file beneath them.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 9,
      "caption": "A cursed tower hums with pale green light.",
      "visual_description": "A leaning stone tower wrapped in glowing ivy, sickly green runes pulsing along its base, the magic helper raising a warding hand.",
      "characters": ["magic_helper", "scout"]
    },
    {
      "scene_number": 10,
      "caption": "A magic door blocks the path to the keep.",
      "visual_description": "A tall obsidian door etched with shifting silver sigils, the magic helper pressing both palms against it as sparks crawl outward.",
      "characters": ["magic_helper", "map_reader"]
    },
    {
      "scene_number": 11,
      "caption": "The door opens onto a vaulted prison hall.",
      "visual_description": "A long stone corridor lined with empty cells, torchlight flickering, a single locked cell at the far end glowing faintly.",
      "characters": ["scout", "magic_helper", "map_reader", "sleepy_official"]
    },
    {
      "scene_number": 12,
      "caption": "They find the captive chained beneath a broken chandelier.",
      "visual_description": "A weary prisoner in tattered noble clothes shackled to a stone bench, dust drifting through shafts of moonlight from a shattered roof.",
      "characters": ["captive", "scout", "map_reader"]
    },
    {
      "scene_number": 13,
      "caption": "The magic helper burns the chains away.",
      "visual_description": "Hands wreathed in blue fire melting iron shackles, the captive shielding their eyes, sparks pooling on the flagstones.",
      "characters": ["captive", "magic_helper"]
    },
    {
      "scene_number": 14,
      "caption": "The armored patrol discovers the open door.",
      "visual_description": "Helmeted guards bursting into the corridor with raised halberds, shouting, torches streaming smoke behind them.",
      "characters": ["armored_patrol"]
    },
    {
      "scene_number": 15,
      "caption": "The team flees through collapsing royal halls.",
      "visual_description": "The five running past toppling columns and falling banners, the sleepy official clutching his kettle, dust billowing behind them.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "captive"]
    },
    {
      "scene_number": 16,
      "caption": "A dragon's shadow sweeps across the rooftops.",
      "visual_description": "An enormous winged silhouette darkening a moonlit avenue, scattering tiles, the team frozen mid-stride in its shadow.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "captive", "dragon"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint onto the long stone bridge.",
      "visual_description": "A narrow arched bridge over a black chasm, wind whipping cloaks, the cursed city burning red behind them, the patrol close on their heels.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "captive", "armored_patrol"]
    },
    {
      "scene_number": 18,
      "caption": "The magic helper shatters the bridge behind them.",
      "visual_description": "A blast of silver light cracking the bridge midspan, stones tumbling into the abyss, the rescued captive looking back as the team reaches the safe far side at dawn.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "captive"]
    }
  ]
}

